INSERT INTO pf_profile (user_id, name_en, name_bn, email, phone_en, phone_bn, github, linkedin, medium, youtube, facebook, x, gitlab, kaggle, resume_url, career_start_year, greeting_en, greeting_bn, title_en, title_bn, subtitle_en, subtitle_bn, slogan_en, slogan_bn, objective_en, objective_bn) VALUES
  ('88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Abir Hosen', 'আবির হোসেন', 'abir71.hosen@gmail.com', '+880 1310 685450', '+৮৮০ ১৩১০ ৬৮৫৪৫০', 'abir-hosen-ashik', 'abir-hosen-ashik', 'abir-hosen-ashik', 'abir-hosen-ashik', 'abirdox', 'abirhosen_ashik', 'abir-hosen', 'abirhosenashik', 'https://tlapmuaszjrzkzccrxkg.supabase.co/storage/v1/object/public/public-bucket/Resume%20-%20Abir%20Hosen.pdf', 2020, 'Hello, I am', 'হ্যালো, আমি', 'AI Engineer & Full-Stack Developer', 'এআই ইঞ্জিনিয়ার ও ফুল-স্ট্যাক ডেভেলপার', 'Building Intelligence that Empowers the World', 'নির্মাণ করছি - অগ্রগতির পথে বিশ্বকে নিয়ে যাওয়া স্মার্ট প্রযুক্তি', 'Turning ideas into intelligent, scalable solutions', 'প্রযুক্তির শক্তিতে নতুন সম্ভাবনার দুয়ার উন্মোচন', 'With <b>over {years} years</b> of experience in <b>backend</b> infrastructure advancement, complemented by <b>3 years</b> in responsive, pixel-perfect <b>frontend</b> engineering and a <b>deep theoretical understanding of AI</b>, paired with 1 year of LLM-focused industry work, I characterize myself as a Full-Spectrum Software Engineer specializing in <b>end-to-end development, deployment and maintenance</b>. I aim to drive the development of secure, maintainable, high-performing systems while contributing to technical decisions, aligning engineering with business goals, and innovating with modern technologies. My expertise in ERP, recruiting platforms, lead generation, sales and marketing automation, dynamic multimedia handling, and <b>Agentic AI</b> development using LLM, RAG, and MCP, combined with skills in database design, clean modular architecture, CI/CD, secure REST/GraphQL APIs, real-time socket systems, event-driven microservices, and translating complex business requirements, enables the delivery of high-impact applications that advance organizational goals.', 'ব্যাকএন্ড ইনফ্রাস্ট্রাকচার উন্নয়নে {years} বছরেরও বেশি অভিজ্ঞতা, তার সাথে ৩ বছরের রেসপন্সিভ ও পিক্সেল-নিখুঁত ফ্রন্টএন্ড ইঞ্জিনিয়ারিং দক্ষতা এবং কৃত্রিম বুদ্ধিমত্তায় গভীর তাত্ত্বিক জ্ঞান, যা ১ বছরের LLM-ভিত্তিক ইন্ডাস্ট্রি অভিজ্ঞতার মাধ্যমে আরও দৃঢ় হয়েছে—এসবের সমন্বয়ে আমি নিজেকে একটি ফুল-স্পেকট্রাম সফটওয়্যার ইঞ্জিনিয়ার হিসেবে পরিচিত করি, যিনি end-to-end ডেভেলপমেন্ট, ডিপ্লয়মেন্ট ও মেইনটেন্যান্স-এ বিশেষজ্ঞ। আমার লক্ষ্য হলো নিরাপদ, রক্ষণাবেক্ষণযোগ্য এবং উচ্চ-কার্যক্ষম সিস্টেম নির্মাণ করা, যেখানে আমি প্রযুক্তিগত সিদ্ধান্ত গ্রহণে অবদান রাখতে পারি, ইঞ্জিনিয়ারিং কার্যক্রমকে ব্যবসার লক্ষ্যগুলোর সাথে সামঞ্জস্য করতে পারি এবং আধুনিক প্রযুক্তি ব্যবহার করে নতুনত্ব আনতে পারি। ERP, রিক্রুটিং প্ল্যাটফর্ম, লিড জেনারেশন, সেলস ও মার্কেটিং অটোমেশন, ডাইনামিক মাল্টিমিডিয়া প্রসেসিং এবং LLM, RAG ও MCP ব্যবহার করে এজেন্টিক এআই ডেভেলপমেন্ট-এ আমার অভিজ্ঞতা, সাথে ডাটাবেস ডিজাইন, পরিচ্ছন্ন মডুলার আর্কিটেকচার, CI/CD, নিরাপদ REST/GraphQL API, রিয়েল-টাইম সকেট সিস্টেম, ইভেন্ট-ড্রিভেন মাইক্রোসার্ভিস এবং জটিল ব্যবসায়িক চাহিদাকে প্রযুক্তিগত সমাধানে রূপান্তরের দক্ষতা—এসব মিলিয়ে আমি এমন উচ্চ-প্রভাবসম্পন্ন অ্যাপ্লিকেশন তৈরি করতে পারি, যা প্রতিষ্ঠানকে তাদের লক্ষ্য অর্জনে এগিয়ে নেয়।')
