  ('2fe73218-6f9b-4671-b7a8-621251e6512b', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'ui.message_failed', 'Failed to send message.', 'বার্তা পাঠানো যায়নি।'),
  ('8524fb6b-42ef-4c28-ad17-f325b43422e6', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'ui.message_sent', 'Message sent successfully!', 'বার্তা সফলভাবে পাঠানো হয়েছে!'),
