  ('dea958c5-9b12-4303-b997-1e6ef784b4b9', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'ui.more_responsibilities', 'more responsibilities...', 'আরও দায়িত্ব...'),
  ('bcf8c745-1277-4cc9-a6d4-2158ad1529be', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'ui.no_projects', 'No projects found for the selected filter.', 'নির্বাচিত ফিল্টারে কোনো প্রকল্প পাওয়া যায়নি।'),
