INSERT INTO pf_about_sections (id, user_id, audience, heading_en, heading_bn, sort_order) VALUES
  ('079dd059-343e-4629-ba3b-10691bdb2244', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'general', 'Who Am I?', 'আমি কে?', 1),
  ('2596b703-2167-484f-bf74-8e0963536476', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'general', 'What I want?', 'আমার লক্ষ্য কী?', 2),
  ('a5e9f069-ae63-4249-9592-d5d9143a5c11', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'general', 'What I Offer?', 'আমি কী অফার করতে পারি?', 3),
  ('7a4852d2-ae61-4cd5-8754-c18f70030c6d', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'client', 'Who Am I?', 'আমি কে?', 1),
  ('3844c1e2-b599-44b0-b2ea-64229838d9c6', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'client', 'What I can do?', 'আমি কি করতে পারি?', 2),
  ('bdf7fa58-7824-4ef8-826e-bfd37d148c03', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'client', 'Why I am important for you?', 'কেন আমি আপনার জন্য গুরুত্বপূর্ণ?', 3)
INSERT INTO pf_about_blocks (id, user_id, section_id, kind, text_en, text_bn, items_en, items_bn, sort_order) VALUES
  ('f599dc52-cd2a-4f2e-9aa4-1abe3e1ed728', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '079dd059-343e-4629-ba3b-10691bdb2244', 'paragraph', 'With <b>over {years}</b> years of hands-on experience in backend infrastructure advancement, I have consistently contributed to the design, development, and optimization of scalable enterprise systems. This journey is complemented by 3 years of expertise in building responsive, pixel-perfect frontend applications that deliver seamless user experiences. Beyond software engineering fundamentals, I hold a deep theoretical foundation in Artificial Intelligence, further strengthened by 1 year of practical, industry-level work focused on large language models (LLMs).', 'ব্যাকএন্ড ইনফ্রাস্ট্রাকচার উন্নয়নে {years} বছরেরও বেশি বাস্তব অভিজ্ঞতার মাধ্যমে, আমি ধারাবাহিকভাবে স্কেলেবল এন্টারপ্রাইজ সিস্টেমের ডিজাইন, ডেভেলপমেন্ট এবং অপ্টিমাইজেশনে অবদান রেখেছি। এই যাত্রা ৩ বছরের বেশি সময়ের রেসপন্সিভ, পিক্সেল-নিখুঁত ফ্রন্টএন্ড অ্যাপ্লিকেশন তৈরি করার দক্ষতার মাধ্যমে পরিপূরক, যা ব্যবহারকারীদের জন্য সহজ এবং স্বচ্ছ অভিজ্ঞতা প্রদান করে। সফটওয়্যার ইঞ্জিনিয়ারিংয়ের মূল ধারণার বাইরে, আমি কৃত্রিম বুদ্ধিমত্তায় (AI) গভীর তাত্ত্বিক জ্ঞান রাখি, যা ১ বছরের LLM-ভিত্তিক শিল্প স্তরের বাস্তব অভিজ্ঞতার মাধ্যমে আরও দৃঢ় হয়েছে।', '{}'::text[], '{}'::text[], 1),
  ('fc4510c9-fef8-4fbe-816f-6a9c9b7f30d9', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '079dd059-343e-4629-ba3b-10691bdb2244', 'paragraph', 'I characterize myself as a Full-Spectrum Software Engineer, specializing in end-to-end development, deployment, and long-term maintenance. My work spans <b>backend services, frontend interfaces, and AI-powered solutions</b>, allowing me to bridge the gap between technical execution and business value. I thrive in environments where innovation, scalability, and reliability are critical, and I bring a problem-solving mindset that balances immediate needs with long-term architectural vision.', 'আমি নিজেকে একটি ফুল-স্পেকট্রাম সফটওয়্যার ইঞ্জিনিয়ার হিসেবে পরিচিত করি, যিনি end-to-end ডেভেলপমেন্ট, ডিপ্লয়মেন্ট এবং দীর্ঘমেয়াদি মেইনটেন্যান্স-এ বিশেষজ্ঞ। আমার কাজের পরিধি ব্যাকএন্ড সার্ভিস, ফ্রন্টএন্ড ইন্টারফেস এবং AI-চালিত সমাধান পর্যন্ত বিস্তৃত, যা প্রযুক্তিগত বাস্তবায়ন এবং ব্যবসায়িক মানের মধ্যে সেতুবন্ধন তৈরি করে। আমি এমন পরিবেশে উজ্জ্বলভাবে কাজ করি যেখানে উদ্ভাবন, স্কেলেবিলিটি এবং নির্ভরযোগ্যতা গুরুত্বপূর্ণ, এবং আমি এমন সমস্যা সমাধানের মনোভাব নিয়ে কাজ করি যা তাৎক্ষণিক প্রয়োজনের সাথে দীর্ঘমেয়াদি আর্কিটেকচারাল দৃষ্টিভঙ্গি সামঞ্জস্য করে।', '{}'::text[], '{}'::text[], 2),
  ('3adc5fed-2c8b-4b91-ad31-1b3a8182bd22', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '2596b703-2167-484f-bf74-8e0963536476', 'paragraph', 'I aspire to contribute not only as a developer but as a strategic partner in shaping technical direction and delivering impactful solutions. My goal is to drive the development of secure, maintainable, and high-performing systems while actively engaging in technical decision-making and architectural planning. I seek opportunities where I can align engineering efforts with broader business goals, ensuring that technology serves as a direct enabler of growth and innovation.', 'আমি কেবল একজন ডেভেলপার হিসেবে নয়, বরং প্রযুক্তিগত দিকনির্দেশনা নির্ধারণ এবং প্রভাবশালী সমাধান প্রদান করার ক্ষেত্রে একটি কৌশলগত অংশীদার হিসেবেও অবদান রাখতে আগ্রহী। আমার লক্ষ্য হলো নিরাপদ, রক্ষণাবেক্ষণযোগ্য এবং উচ্চ-কার্যক্ষম সিস্টেমের উন্নয়ন চালানো, যেখানে আমি সক্রিয়ভাবে প্রযুক্তিগত সিদ্ধান্ত গ্রহণ এবং আর্কিটেকচার পরিকল্পনায় অংশগ্রহণ করি। আমি এমন সুযোগ খুঁজি যেখানে আমি ইঞ্জিনিয়ারিং প্রচেষ্টাকে বৃহত্তর ব্যবসায়িক লক্ষ্যগুলোর সাথে সামঞ্জস্য করতে পারি, নিশ্চিত করে যে প্রযুক্তি সরাসরি বৃদ্ধি এবং উদ্ভাবনের সহায়ক হিসাবে কাজ করে।', '{}'::text[], '{}'::text[], 1),
  ('66cc377a-8a80-4060-8f52-3ac0e402afb2', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '2596b703-2167-484f-bf74-8e0963536476', 'paragraph', 'I want to play a central role in mentoring developers, leading teams, and managing complex projects, fostering a culture of collaboration and knowledge-sharing. Beyond code, I aim to optimize enterprise-grade applications for scalability, reliability, and high availability, while continuously improving security practices and compliance awareness.', 'আমি ডেভেলপারদের মেন্টরিং, টিম লিড এবং জটিল প্রকল্প পরিচালনায় কেন্দ্রীয় ভূমিকা পালন করতে চাই, এমন একটি পরিবেশ গড়ে তুলতে যেখানে সহযোগিতা এবং জ্ঞানের ভাগাভাগি উৎসাহিত হয়। কেবল কোডের বাইরে, আমি এন্টারপ্রাইজ-গ্রেড অ্যাপ্লিকেশনকে স্কেলেবিলিটি, নির্ভরযোগ্যতা এবং উচ্চ প্রাপ্যতার জন্য অপ্টিমাইজ করতে চাই, সাথে সাথে নিরাপত্তা প্রক্রিয়া এবং কমপ্লায়েন্স সচেতনতা ক্রমাগত উন্নত করতে চাই।', '{}'::text[], '{}'::text[], 2),
  ('65532e00-7c80-4bad-b9ad-7e44639bce0e', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '2596b703-2167-484f-bf74-8e0963536476', 'paragraph', 'Equally, I am driven to stay ahead of the curve by introducing modern tools, frameworks, and methodologies, carefully balancing technical debt with the pursuit of new features. Ultimately, I want to contribute to building sustainable engineering practices that not only solve immediate challenges but also set a long-term technology roadmap aligned with the company’s vision.', 'একইভাবে, আমি সর্বদা আধুনিক টুল, ফ্রেমওয়ার্ক এবং পদ্ধতি প্রবর্তনের মাধ্যমে প্রযুক্তিগত অগ্রগতির সঙ্গে সামঞ্জস্য রাখার চেষ্টা করি, যেখানে নতুন ফিচারের প্রয়াসের সঙ্গে প্রযুক্তিগত দেন-দেনের (technical debt) মধ্যে সূক্ষ্ম ভারসাম্য বজায় থাকে। শেষ পর্যন্ত, আমি এমন টেকসই ইঞ্জিনিয়ারিং প্র্যাকটিস তৈরি করতে অবদান রাখতে চাই, যা কেবল তাৎক্ষণিক চ্যালেঞ্জ সমাধান করে না, বরং দীর্ঘমেয়াদি প্রযুক্তি রোডম্যাপ নির্ধারণ করে যা কোম্পানির ভিশনের সাথে সামঞ্জস্যপূর্ণ।', '{}'::text[], '{}'::text[], 3),
  ('e5bd8261-4179-4255-9ac4-1e0b9538c0c6', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'a5e9f069-ae63-4249-9592-d5d9143a5c11', 'paragraph', 'I bring a unique combination of technical expertise, cross-domain experience, and business-oriented thinking that enables me to deliver software solutions with both immediate impact and long-term value. My track record spans diverse domains including ERP systems, recruiting platforms, lead generation tools, sales and marketing automation, dynamic multimedia processing, and Agentic AI development leveraging cutting-edge techniques such as LLMs, Retrieval-Augmented Generation (RAG), and Model Context Protocol (MCP).', 'আমি প্রযুক্তিগত দক্ষতা, ক্রস-ডোমেইন অভিজ্ঞতা এবং ব্যবসা-কেন্দ্রিক চিন্তাধারার একটি অনন্য সমন্বয় নিয়ে আসি, যা আমাকে এমন সফটওয়্যার সমাধান প্রদান করতে সক্ষম করে যা একদিকে তাৎক্ষণিক প্রভাব ফেলে এবং অন্যদিকে দীর্ঘমেয়াদী মূল্য যোগ করে। আমার অভিজ্ঞতা বিস্তৃত বিভিন্ন ক্ষেত্রে, যেমন ERP সিস্টেম, রিক্রুটিং প্ল্যাটফর্ম, লিড জেনারেশন টুল, সেলস ও মার্কেটিং অটোমেশন, ডায়নামিক মাল্টিমিডিয়া প্রসেসিং, এবং Agentic AI ডেভেলপমেন্ট—যেখানে LLMs, Retrieval-Augmented Generation (RAG), এবং Model Context Protocol (MCP)-এর মতো সর্বাধুনিক কৌশল ব্যবহার করা হয়েছে।', '{}'::text[], '{}'::text[], 1),
  ('1ef59fd0-c255-4ca5-9f25-0c151a2fc9ec', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'a5e9f069-ae63-4249-9592-d5d9143a5c11', 'paragraph', 'On the engineering side, I specialize in database schema design, clean and modular architecture, and scalable backend systems, complemented by skills in building secure REST/GraphQL APIs, real-time socket-based applications, and event-driven microservices. I am proficient in setting up CI/CD pipelines and DevOps workflows, ensuring smooth delivery, deployment, and long-term maintainability of applications.', 'ইঞ্জিনিয়ারিং-এর ক্ষেত্রে আমি ডাটাবেজ স্কিমা ডিজাইন, পরিষ্কার ও মডুলার আর্কিটেকচার, এবং স্কেলযোগ্য ব্যাকএন্ড সিস্টেমে বিশেষজ্ঞ। পাশাপাশি, সিকিউর REST/GraphQL API, রিয়েল-টাইম সকেট-ভিত্তিক অ্যাপ্লিকেশন, এবং ইভেন্ট-ড্রিভেন মাইক্রোসার্ভিস তৈরির দক্ষতা রয়েছে। আমি CI/CD পাইপলাইন এবং DevOps ওয়ার্কফ্লো সেটআপে দক্ষ, যা অ্যাপ্লিকেশনের মসৃণ ডেলিভারি, ডেপ্লয়মেন্ট, এবং দীর্ঘমেয়াদী মেইনটেইনেবিলিটি নিশ্চিত করে।', '{}'::text[], '{}'::text[], 2),
  ('5cc8ead8-6508-4817-a986-01ae357f4a57', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'a5e9f069-ae63-4249-9592-d5d9143a5c11', 'paragraph', 'What truly differentiates me is my ability to translate complex business requirements into robust, production-grade technical solutions. By collaborating with stakeholders and cross-functional teams, I ensure that engineering outcomes align with organizational goals, whether the focus is on optimizing performance, improving reliability, or innovating with modern technologies.', 'যা আমাকে সত্যিই আলাদা করে তোলে তা হলো জটিল ব্যবসায়িক প্রয়োজনীয়তাকে দৃঢ়, প্রোডাকশন-গ্রেড টেকনিক্যাল সলিউশনে রূপান্তর করার ক্ষমতা। স্টেকহোল্ডার এবং ক্রস-ফাংশনাল টিমের সঙ্গে সহযোগিতা করে আমি নিশ্চিত করি যে ইঞ্জিনিয়ারিং ফলাফলগুলো সাংগঠনিক লক্ষ্যের সঙ্গে সামঞ্জস্যপূর্ণ—হোক সেটা পারফরম্যান্স অপ্টিমাইজেশন, রিলায়েবিলিটি উন্নয়ন, কিংবা আধুনিক প্রযুক্তির মাধ্যমে ইনোভেশন।', '{}'::text[], '{}'::text[], 3),
  ('d54c2722-0a2c-4037-9d73-c4ac753d3e90', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'a5e9f069-ae63-4249-9592-d5d9143a5c11', 'paragraph', 'In short, I offer the expertise to design, build, and scale high-impact applications, while also providing the vision, adaptability, and problem-solving mindset needed to advance both technical excellence and business success.', 'সংক্ষেপে, আমি উচ্চ-প্রভাবশালী অ্যাপ্লিকেশন ডিজাইন, তৈরি এবং স্কেল করার দক্ষতা প্রদান করি। পাশাপাশি, প্রযুক্তিগত উৎকর্ষ ও ব্যবসায়িক সফলতাকে এগিয়ে নিতে প্রয়োজনীয় ভিশন, অভিযোজনযোগ্যতা, এবং সমস্যা সমাধানের মানসিকতাও প্রদান করি।', '{}'::text[], '{}'::text[], 4),
  ('3e0e76e9-1151-4173-afa1-f74eb91e9e2d', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '7a4852d2-ae61-4cd5-8754-c18f70030c6d', 'paragraph', 'I am a full-spectrum software engineer who understands both business needs and technical solutions. For <b>over {years} years</b>, I have worked on designing and developing <b>backend</b> systems that ensure enterprise data and services are secure, fast, and reliable. Alongside this, I have over 3 years of experience in <b>frontend</b> or user interface design, creating applications that are easy, visually appealing, and efficient for users.', 'আমি একজন পূর্ণাঙ্গ সফটওয়্যার ইঞ্জিনিয়ার, যিনি ব্যবসায়িক প্রয়োজন এবং প্রযুক্তিগত সমাধান—উভয়ই ভালোভাবে বুঝি। গত {years} বছরের বেশি সময় ধরে আমি ব্যাকএন্ড সিস্টেম ডিজাইন ও ডেভেলপমেন্টে কাজ করেছি, যা এন্টারপ্রাইজ ডেটা এবং সার্ভিসকে নিরাপদ, দ্রুত ও নির্ভরযোগ্য রাখে। পাশাপাশি, আমি ৩ বছরেরও বেশি সময় ধরে ফ্রন্টএন্ড বা ইউজার ইন্টারফেস ডিজাইনে অভিজ্ঞ, যেখানে ব্যবহারকারীদের জন্য সহজ, দৃষ্টিনন্দন এবং কার্যকর অ্যাপ্লিকেশন তৈরি করেছি।', '{}'::text[], '{}'::text[], 1),
  ('cad16ece-fdeb-4354-8695-b86284db6762', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '7a4852d2-ae61-4cd5-8754-c18f70030c6d', 'paragraph', 'I have also worked with <b>Artificial Intelligence (AI)</b> and <b>Large Language Models (LLMs)</b>, which allows me to leverage technology for <b>complex data analysis, automation, and decision-making to benefit your business.</b>', 'আমি কৃত্রিম বুদ্ধিমত্তা (AI) এবং বড় ভাষা মডেল (LLMs) নিয়েও কাজ করেছি, যা আমাকে জটিল ডেটা বিশ্লেষণ, অটোমেশন এবং সিদ্ধান্ত গ্রহণে প্রযুক্তিকে ব্যবহার করার সুযোগ দেয়—যা আপনার ব্যবসার জন্য উপকারী হতে পারে।', '{}'::text[], '{}'::text[], 2),
  ('bec6e8e0-441c-4380-91cf-c09e0e8153e3', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '3844c1e2-b599-44b0-b2ea-64229838d9c6', 'paragraph', 'I develop software that makes your business operations faster, safer, and easier. For example, I can create <b>ERP systems, recruiting platforms, lead generation tools, and sales & marketing automation</b>, helping your team save time and achieve better results. Additionally, I can develop <b>multimedia, video, or audio processing</b> solutions and <b>AI-powered smart applications</b> to make your business more modern and efficient.', 'আমি এমন সফটওয়্যার তৈরি করি যা আপনার ব্যবসার কাজকে দ্রুততর, নিরাপদ এবং সহজ করে তোলে। উদাহরণস্বরূপ, আমি ERP সিস্টেম, রিক্রুটিং প্ল্যাটফর্ম, লিড জেনারেশন টুল এবং সেলস ও মার্কেটিং অটোমেশন সলিউশন তৈরি করতে পারি, যা আপনার টিমকে সময় বাঁচাতে এবং আরও ভালো ফলাফল অর্জনে সহায়তা করবে। এছাড়াও, আমি মাল্টিমিডিয়া, ভিডিও বা অডিও প্রসেসিং সলিউশন এবং AI-চালিত স্মার্ট অ্যাপ্লিকেশন তৈরি করতে পারি, যা আপনার ব্যবসাকে আরও আধুনিক ও কার্যকর করবে।', '{}'::text[], '{}'::text[], 1),
  ('2c40f0b1-bbd1-4a8c-95fe-d96e6dd4f0a5', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', '3844c1e2-b599-44b0-b2ea-64229838d9c6', 'paragraph', 'I ensure that your software is secure, user-friendly, and sustainable over time. I can provide customized solutions tailored to your business needs, allowing you to focus on achieving your goals.', 'আমি নিশ্চিত করি যে আপনার সফটওয়্যার নিরাপদ, ব্যবহারবান্ধব এবং দীর্ঘমেয়াদে টেকসই হয়। আমি আপনার ব্যবসার প্রয়োজন অনুযায়ী কাস্টমাইজড সলিউশন দিতে পারি, যাতে আপনি আপনার মূল লক্ষ্য অর্জনে মনোযোগ দিতে পারেন।', '{}'::text[], '{}'::text[], 2),
  ('e09814b2-d9c8-4397-8b21-420d00aaa23a', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'bdf7fa58-7824-4ef8-826e-bfd37d148c03', 'paragraph', 'I don’t just write code—I understand business problems and solve them through technology. The core focus of my work is:', 'আমি শুধু কোড লিখি না—আমি ব্যবসায়িক সমস্যাগুলো বুঝে তা প্রযুক্তির মাধ্যমে সমাধান করি। আমার কাজের মূল লক্ষ্য হলো:', '{}'::text[], '{}'::text[], 1),
  ('c32c8c88-631b-4e9e-b56f-94896e8fe691', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'bdf7fa58-7824-4ef8-826e-bfd37d148c03', 'list', NULL, NULL, ARRAY['Keeping data and information <b>secure</b>', 'Ensuring software is <b>fast and reliable</b>', 'Adding new features and <b>fixing</b> existing issues', 'Making your team’s <b>work easier</b>']::text[], ARRAY['ডেটা ও তথ্য নিরাপদ রাখা', 'সফটওয়্যারকে দ্রুত ও নির্ভরযোগ্য রাখা', 'নতুন ফিচার যোগ করা এবং বিদ্যমান সমস্যাগুলো সমাধান করা', 'আপনার টিমের কাজকে আরও সহজ করা']::text[], 2),
  ('56c6ec02-700b-43b0-a56c-0b8674a7c839', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'bdf7fa58-7824-4ef8-826e-bfd37d148c03', 'paragraph', 'As a client, you want software that is <b>long-lasting, user-friendly, secure</b>, and <b>high-quality</b>. I am here to make sure your technology achieves these goals.', 'একজন ক্লায়েন্ট হিসেবে, আপনি এমন সফটওয়্যার চান যা দীর্ঘস্থায়ী, ব্যবহারবান্ধব, নিরাপদ এবং উচ্চমানের। আমি এখানে আছি যাতে আপনার প্রযুক্তি এসব লক্ষ্য পূরণ করে।', '{}'::text[], '{}'::text[], 3)
INSERT INTO pf_education (id, user_id, degree_en, degree_bn, institution_en, institution_bn, year_en, year_bn, location_en, location_bn, sort_order) VALUES
  ('d49073e9-2a16-4193-8302-cd5ff3bf898c', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'MSc - Information & Communication Engineering', 'এমএসসি - তথ্য ও যোগাযোগ প্রকৌশল', 'Noakhali Science & Technology University', 'নোয়াখালী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয়', '2023', '২০২৩', 'Noakhali, Chittagong', 'নোয়াখালী, চট্টগ্রাম', 1),
