INSERT INTO pf_projects (id, user_id, title_en, title_bn, duration_en, duration_bn, description_en, description_bn, responsibilities_en, responsibilities_bn, tech_stack, link, is_featured, sort_order) VALUES
  ('08152fc9-7375-46b8-8f4c-510346406064', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Jamahook – AI Music Generator', 'জামাহুক – এআই মিউজিক জেনারেটর', 'May 2025 - Present', 'মে ২০২৫ - বর্তমান', 'AI-powered music production enhancement feature enabling solo instrumental generation using Stable Audio open models.', 'স্টেবল অডিও ওপেন মডেল ব্যবহার করে একক যন্ত্রসংগীত তৈরির এআই-চালিত মিউজিক প্রোডাকশন উন্নতিকরণ ফিচার।', ARRAY['Designed & developed Stable Audio-based solo music generation feature service', 'Analyzed platform requirements and constraints to choose optimal deployment architecture', 'Integrated into Jamahook''s real-time DAW assistant system']::text[], ARRAY['স্টেবল অডিও-ভিত্তিক একক সংগীত তৈরির ফিচার সার্ভিস ডিজাইন ও ডেভেলপ করেছি', 'সর্বোত্তম ডিপ্লয়মেন্ট আর্কিটেকচার নির্বাচনের জন্য প্ল্যাটফর্ম প্রয়োজনীয়তা বিশ্লেষণ করেছি', 'জামাহুকের রিয়েল-টাইম DAW সহায়ক সিস্টেমে একীভূত করেছি']::text[], ARRAY['AI/ML', 'Stable Audio', 'Python', 'FastAPI', 'Docker']::text[], NULL, true, 1),
  ('35bb87df-21ac-4540-822a-1167a5b609a4', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Chat Brokers', 'চ্যাট ব্রোকার্স', 'March 2025 - May 2025', 'মার্চ ২০২৫ - মে ২০২৫', 'AI and LLM-powered broker info chat system using RAG and MCP enabled dynamic context-aware conversations.', 'RAG এবং MCP ব্যবহার করে গতিশীল প্রসঙ্গ-সচেতন কথোপকথন সক্ষম এআই এবং LLM-চালিত ব্রোকার তথ্য চ্যাট সিস্টেম।', ARRAY['Data ingestion and structuring pipeline for diverse broker profiles', 'RAG and MCP toolset enabling intelligent comparison and recommendations', 'End-to-end system architecture and data modeling']::text[], ARRAY['বিভিন্ন ব্রোকার প্রোফাইলের জন্য ডেটা ইনজেশন এবং স্ট্রাকচারিং পাইপলাইন', 'বুদ্ধিমান তুলনা এবং সুপারিশ সক্ষম RAG এবং MCP টুলসেট', 'এন্ড-টু-এন্ড সিস্টেম আর্কিটেকচার এবং ডেটা মডেলিং']::text[], ARRAY['LangChain', 'RAG', 'MCP', 'Python', 'FastAPI', 'PostgreSQL']::text[], NULL, true, 2),
  ('3a56f2ce-272a-4a7f-9c8e-344d5c57382c', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Cannella Recruitment Service (AI)', 'কানেলা রিক্রুটমেন্ট সার্ভিস (এআই)', 'Feb 2025 - April 2025', 'ফেব্রুয়ারি ২০২৫ - এপ্রিল ২০২৫', 'AI-powered job platform that streamlines hiring by intelligently matching job requirements with applicant CVs.', 'এআই-চালিত জব প্ল্যাটফর্ম যা চাকরির চাহিদা এবং আবেদনকারীর সিভি বুদ্ধিমত্তার সাথে মিলিয়ে নিয়োগ প্রক্রিয়াকে সহজ করে।', ARRAY['Developed AI models to analyze and match job requirements with CVs', 'Implemented machine learning algorithms for candidate-job ranking', 'Optimized system for accurate and efficient job matching']::text[], ARRAY['চাকরির চাহিদা ও সিভি বিশ্লেষণ ও মিলানোর জন্য এআই মডেল তৈরি', 'প্রার্থী-চাকরি র‍্যাংকিংয়ের জন্য মেশিন লার্নিং অ্যালগরিদম প্রয়োগ', 'নির্ভুল ও কার্যকরী জব ম্যাচিংয়ের জন্য সিস্টেম অপ্টিমাইজেশন']::text[], ARRAY['Machine Learning', 'NLP', 'Python', 'Scikit-learn', 'PostgreSQL']::text[], NULL, true, 3),
  ('e0fbe06a-2f40-48f3-92cc-c2d7c29d23ef', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Query AI', 'কোয়েরি এআই', 'Oct 2024 - Jan 2025', 'অক্টোবর ২০২৪ - জানুয়ারি ২০২৫', 'NLP-based solution that generates and executes SQL queries from user prompts, bridging user intent and data insights.', 'এনএলপি-ভিত্তিক সমাধান যা ব্যবহারকারীর প্রম্পট থেকে এসকিউএল কোয়েরি তৈরি ও কার্যকর করে, ব্যবহারকারীর উদ্দেশ্য এবং ডেটা ইনসাইটের মধ্যে সেতুবন্ধন করে।', ARRAY['Developed FastAPI backend for the project', 'Designed and optimized PostgreSQL and pgVector for storage', 'Responsible for complete database design']::text[], ARRAY['প্রকল্পের জন্য FastAPI ব্যাকএন্ড তৈরি', 'সংরক্ষণের জন্য PostgreSQL ও pgVector ডিজাইন ও অপ্টিমাইজ করা', 'সম্পূর্ণ ডাটাবেস ডিজাইনের দায়িত্ব পালন']::text[], ARRAY['NLP', 'FastAPI', 'PostgreSQL', 'pgVector', 'Python']::text[], NULL, true, 4),
  ('83530931-f34b-48e0-9dd8-30480a3c740b', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Probashkormi', 'প্রবাসকর্মী', 'Aug 2023 - Ongoing', 'আগস্ট ২০২৩ - চলমান', 'Recruitment management system for individuals seeking jobs abroad, eliminating middlemen.', 'বিদেশে চাকরি খোঁজার জন্য ব্যক্তিদের জন্য রিক্রুটমেন্ট ম্যানেজমেন্ট সিস্টেম, মধ্যস্বত্বভোগীদের সরিয়ে।', ARRAY['Developed backend with NestJS, Prisma, GraphQL and MongoDB', 'Integrated AWS S3 for file storage', 'Responsible for complete DB design and API pipeline']::text[], ARRAY['NestJS, Prisma, GraphQL এবং MongoDB দিয়ে ব্যাকএন্ড ডেভেলপ করা', 'ফাইল সংরক্ষণের জন্য AWS S3 ইন্টিগ্রেট করা', 'সম্পূর্ণ ডাটাবেস ডিজাইন এবং API পাইপলাইন এর দায়িত্বে ছিলাম']::text[], ARRAY['NestJS', 'GraphQL', 'MongoDB', 'AWS S3', 'Prisma']::text[], NULL, false, 5),
  ('b6ec7c81-60bd-4878-af72-c01cf381c9fd', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Singistic', 'সিংগিস্টিক', 'March 2023 - Aug 2023', 'মার্চ ২০২৩ - আগস্ট ২০২৩', 'An online karaoke app for Web, Android and iOS users with a wide range of songs in multiple languages.', 'ওয়েব, অ্যান্ড্রয়েড এবং iOS ব্যবহারকারীদের জন্য অনলাইন কারাওকে অ্যাপ, যা একাধিক ভাষায় বিস্তৃত গান সমর্থন করে।', ARRAY['Developed backend with NestJS and DynamoDB', 'Implemented audio processing using ffmpeg, Spleeter and ImageMagick', 'Managed file storage with AWS S3']::text[], ARRAY['NestJS এবং DynamoDB দিয়ে ব্যাকএন্ড ডেভেলপ করা', 'ffmpeg, Spleeter এবং ImageMagick ব্যবহার করে অডিও প্রসেসিং বাস্তবায়ন', 'AWS S3 দিয়ে ফাইল সংরক্ষণ ব্যবস্থাপনা করা']::text[], ARRAY['NestJS', 'DynamoDB', 'AWS S3', 'FFmpeg', 'Spleeter']::text[], NULL, false, 6),
  ('53b2f5d1-a991-459b-a470-e8cea86508c3', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'MashAllah Ecommerce', 'মাশআল্লাহ ই-কমার্স', 'Feb 2024 - Nov 2024', 'ফেব্রুয়ারি ২০২৪ - নভেম্বর ২০২৪', 'A scalable e-commerce platform built with microservices and microfrontend architecture. Features modules for e-commerce, inventory management, order processing and admin controls.', 'মাইক্রোসার্ভিস ও মাইক্রোফ্রন্টএন্ড আর্কিটেকচারে তৈরি একটি স্কেলযোগ্য ই-কমার্স প্ল্যাটফর্ম। ই-কমার্স, ইনভেন্টরি ম্যানেজমেন্ট, অর্ডার প্রসেসিং এবং অ্যাডমিন কন্ট্রোলের মডিউলগুলো অন্তর্ভুক্ত।', ARRAY['Developed Spring Boot microservices and Next.js microfrontend architecture', 'Designed and implemented PostgreSQL database schema', 'Utilized Docker for project virtualization']::text[], ARRAY['Spring Boot মাইক্রোসার্ভিস ও Next.js মাইক্রোফ্রন্টএন্ড আর্কিটেকচার ডেভেলপ করা', 'PostgreSQL ডাটাবেস স্কিমা ডিজাইন ও ইমপ্লিমেন্ট করা', 'প্রকল্প ভার্চুয়ালাইজেশনের জন্য Docker ব্যবহার করা']::text[], ARRAY['Spring Boot', 'Next.js', 'PostgreSQL', 'Docker', 'Microservices']::text[], NULL, false, 7),
  ('093f4b5f-ed15-4720-9085-8c596a11236b', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'SoftCollab', 'সফটকোল্যাব', 'April 2023 - Ongoing', 'এপ্রিল ২০২৩ - চলমান', 'A platform for sharing and collaborating on music files between producers and musicians.', 'প্রযোজক ও সঙ্গীতশিল্পীদের মধ্যে মিউজিক ফাইল শেয়ারিং ও সহযোগিতার জন্য একটি প্ল্যাটফর্ম।', ARRAY['Upgraded backend using ExpressJS, SocketIO and MySQL', 'Utilized ffmpeg and ImageMagick for audio processing', 'Integrated AWS S3 for file management']::text[], ARRAY['ExpressJS, SocketIO এবং MySQL ব্যবহার করে ব্যাকএন্ড উন্নত করা', 'অডিও প্রসেসিংয়ের জন্য ffmpeg ও ImageMagick ব্যবহার করা', 'ফাইল ব্যবস্থাপনার জন্য AWS S3 ইন্টিগ্রেট করা']::text[], ARRAY['ExpressJS', 'SocketIO', 'MySQL', 'AWS S3', 'FFmpeg']::text[], NULL, false, 8),
  ('af890fba-bc83-4a86-9e85-2b0f7b79a694', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Cloud Infra', 'ক্লাউড ইনফ্রা', 'May 2021 - July 2022', 'মে ২০২১ - জুলাই ২০২২', 'Cloud server management platform designed to streamline the management of web servers for business owners. Offers automated backups, server monitoring and deployment tools.', 'ব্যবসার মালিকদের জন্য ওয়েব সার্ভার ব্যবস্থাপনাকে সহজতর করার জন্য ডিজাইনকৃত ক্লাউড সার্ভার ম্যানেজমেন্ট প্ল্যাটফর্ম। স্বয়ংক্রিয় ব্যাকআপ, সার্ভার মনিটরিং এবং ডিপ্লয়মেন্ট টুল সরবরাহ করে।', ARRAY['Developed frontend using ReactJS, Redux and Axios', 'Worked with Docker for project virtualization', 'Integrated Keycloak for SSO']::text[], ARRAY['ReactJS, Redux এবং Axios দিয়ে ফ্রন্টএন্ড ডেভেলপ করা', 'প্রকল্প ভার্চুয়ালাইজেশনের জন্য Docker ব্যবহার করা', 'SSO এর জন্য Keycloak ইন্টিগ্রেট করা']::text[], ARRAY['ReactJS', 'Redux', 'Docker', 'Keycloak', 'Axios']::text[], NULL, false, 9),
  ('9fd75c58-4338-4997-b57b-ada6ac4e669f', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Roboket - Marketing Automation System', 'রোবোকেট - মার্কেটিং অটোমেশন সিস্টেম', 'Feb 2021 - March 2023', 'ফেব্রুয়ারি ২০২১ - মার্চ ২০২৩', 'Marketing automation software that integrates lead-generation tools with social media and communication platforms.', 'মার্কেটিং অটোমেশন সফটওয়্যার যা লিড-জেনারেশন টুলগুলোকে সোশ্যাল মিডিয়া এবং যোগাযোগ প্ল্যাটফর্মের সাথে একত্রিত করে।', ARRAY['Upgraded backend in microservice architecture using FastAPI', 'Worked with Keycloak for SSO and Docker for project virtualization', 'Managed frontend components using ReactJS and Redux']::text[], ARRAY['FastAPI ব্যবহার করে মাইক্রোসার্ভিস আর্কিটেকচারে ব্যাকএন্ড আপগ্রেড করা', 'SSO এর জন্য Keycloak এবং প্রকল্প ভার্চুয়ালাইজেশনের জন্য Docker ব্যবহার করা', 'ReactJS ও Redux দিয়ে ফ্রন্টএন্ড কম্পোনেন্টস পরিচালনা করা']::text[], ARRAY['FastAPI', 'ReactJS', 'Redux', 'Keycloak', 'Docker']::text[], NULL, false, 10),
  ('441ab8a7-caa3-4e4f-b0a8-647ad97c5b05', '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'Tiger ERP', 'টাইগার ইআরপি', 'Jan 2020 - Jan 2021', 'জানুয়ারি ২০২০ - জানুয়ারি ২০২১', 'Enterprise resource planning (ERP) solution designed to manage various business operations like inventory, sales, procurement and accounting.', 'এন্টারপ্রাইজ রিসোর্স প্ল্যানিং (ERP) সমাধান যা বিভিন্ন ব্যবসায়িক অপারেশন যেমন ইনভেন্টরি, বিক্রয়, ক্রয় এবং হিসাব পরিচালনা করার জন্য ডিজাইন করা হয়েছে।', ARRAY['Developed both backend and frontend with Spring Boot and AngularJS', 'Designed database schema and created custom queries', 'Developed secure authentication and API pipeline using JWT']::text[], ARRAY['Spring Boot ও AngularJS ব্যবহার করে ব্যাকএন্ড ও ফ্রন্টএন্ড ডেভেলপ করা', 'ডাটাবেস স্কিমা ডিজাইন এবং কাস্টম কুয়েরি তৈরি করা', 'JWT ব্যবহার করে নিরাপদ অথেনটিকেশন এবং API পাইপলাইন ডেভেলপ করা']::text[], ARRAY['Spring Boot', 'AngularJS', 'JWT', 'MySQL', 'Maven']::text[], NULL, false, 11)
